action.command:
node -e "
const data = require('fs').readFileSync(0, 'utf8');
const event = JSON.parse(data);
const file = event.file || '';
const fs = require('fs');
if (!fs.existsSync(file)) process.exit(0);
const src = fs.readFileSync(file, 'utf8');
const interactiveRe = /<(button|input|select|a )[^>]*>/g;
const ariaRe = /aria-label=/;
const textRe = />([^<]{1,})</;
let match;
let warnings = [];
while ((match = interactiveRe.exec(src)) !== null) {
  const tag = match[0];
  const context = src.slice(Math.max(0, match.index), match.index + 200);
  if (!ariaRe.test(tag) && !textRe.test(context)) {
    warnings.push('Line ~' + (src.slice(0, match.index).split('\n').length) + ': ' + tag.slice(0, 80) + ' — missing aria-label and visible text');
  }
}
if (warnings.length > 0) {
  console.warn('Accessibility warnings in ' + file + ':\n' + warnings.join('\n'));
}
"
